# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# edm_gpedm_reference ----
## IO correctness ----
test_that("GP-EDM matches the GPEDM README training/test example", {
  #' @description FIMS embeddings and direct and TMB GP predictions match the independent GPEDM population-A example.
  clear()
  withr::defer(clear())
  reference <- readRDS(test_path("fixtures", "edm-gpedm-reference.rds"))

  library_embedding <- methods::new(DelayEmbedding)
  library_embedding$construct(
    reference[["training_series"]],
    reference[["embedding_dimension"]],
    reference[["time_lag"]],
    reference[["forecast_horizon"]]
  )
  test_embedding <- methods::new(DelayEmbedding)
  test_embedding$construct(
    reference[["test_series"]],
    reference[["embedding_dimension"]],
    reference[["time_lag"]],
    reference[["forecast_horizon"]]
  )

  # GPEDM keeps the first two rows as NA; FIMS omits incomplete lag rows.
  training_rows <- which(stats::complete.cases(reference[["training_predictors"]]))
  test_rows <- which(stats::complete.cases(reference[["test_predictors"]]))
  expect_length(training_rows, 38L)
  expect_length(test_rows, 8L)
  library_matrix <- matrix(
    library_embedding[["embedded_values"]]$get_values(),
    ncol = reference[["embedding_dimension"]],
    byrow = TRUE
  )
  test_matrix <- matrix(
    test_embedding[["embedded_values"]]$get_values(),
    ncol = reference[["embedding_dimension"]],
    byrow = TRUE
  )
  expect_equal(
    library_matrix, reference[["training_predictors"]][training_rows, ]
  )
  expect_equal(test_matrix, reference[["test_predictors"]][test_rows, ])
  expect_equal(
    library_embedding[["target_values"]]$get_values(),
    reference[["in_sample"]][["obs"]][training_rows]
  )
  expect_equal(
    test_embedding[["target_values"]]$get_values(),
    reference[["out_of_sample"]][["obs"]][test_rows]
  )

  # Match GPEDM's default global scaling, separately for each lag and target.
  scaling <- reference[["scaling"]]
  expect_identical(scaling[["scaling"]], "global")
  library_matrix <- sweep(library_matrix, 2, scaling[["xmeans"]], "-") |>
    sweep(2, scaling[["xsds"]], "/")
  test_matrix <- sweep(test_matrix, 2, scaling[["xmeans"]], "-") |>
    sweep(2, scaling[["xsds"]], "/")
  library_embedding[["embedded_values"]]$set_values(as.numeric(t(library_matrix)))
  test_embedding[["embedded_values"]]$set_values(as.numeric(t(test_matrix)))
  library_embedding[["target_values"]]$set_values(
    (reference[["training_series"]][training_rows] - scaling[["ymeans"]]) /
      scaling[["ysds"]]
  )

  # Reuse GPEDM's fitted parameters to test prediction, not optimizer agreement.
  parameters <- reference[["parameters"]]
  projection <- methods::new(GPEdmProjection)
  projection[["embedding_dimension"]] <- reference[["embedding_dimension"]]
  projection[["phi"]] <- unname(parameters[grep("^phi", names(parameters))])
  projection[["sigma2"]] <- unname(parameters[["sigma2"]])
  projection[["ve"]] <- unname(parameters[["ve"]])
  projection[["forecast_horizon"]] <- reference[["forecast_horizon"]]
  projection[["lib_de_id"]] <- library_embedding$get_id()
  projection[["test_de_id"]] <- test_embedding$get_id()

  in_sample <- projection$predict(
    library_embedding$get_id(), library_embedding$get_id()
  )
  out_of_sample <- projection$predict(
    library_embedding$get_id(), test_embedding$get_id()
  )
  expected_in_sample <- reference[["in_sample"]][["predmean"]][training_rows]
  expected_out_of_sample <- reference[["out_of_sample"]][["predmean"]][test_rows]
  expect_true(all(is.finite(in_sample)))
  expect_true(all(is.finite(out_of_sample)))
  expect_equal(
    in_sample * scaling[["ysds"]] + scaling[["ymeans"]],
    expected_in_sample,
    tolerance = 1e-8
  )
  expect_equal(
    out_of_sample * scaling[["ysds"]] + scaling[["ymeans"]],
    expected_out_of_sample,
    tolerance = 1e-8
  )

  # Fitting also replaces phi, so check that path reaches the TMB model too.
  fitted_projection <- methods::new(GPEdmProjection)
  fitted_projection[["embedding_dimension"]] <- reference[["embedding_dimension"]]
  fitted_projection[["lib_de_id"]] <- library_embedding$get_id()
  fitted_projection[["test_de_id"]] <- test_embedding$get_id()
  fitted_projection$fit(library_embedding$get_id())
  fitted_predictions <- fitted_projection$predict(
    library_embedding$get_id(), test_embedding$get_id()
  )

  expect_no_error(CreateTMBModel())
  objective <- TMB::MakeADFun(
    data = list(),
    parameters = list(p = get_fixed(), re = get_random()),
    DLL = "FIMS",
    silent = TRUE
  )
  objective$report()
  projection$finalize()
  model_predictions <- projection[["predictions"]]$get_values()
  expect_length(model_predictions, length(test_rows))
  expect_true(all(is.finite(model_predictions)))
  expect_equal(
    model_predictions * scaling[["ysds"]] + scaling[["ymeans"]],
    expected_out_of_sample,
    tolerance = 1e-8
  )
  fitted_projection$finalize()
  expect_equal(
    fitted_projection[["predictions"]]$get_values(),
    fitted_predictions,
    tolerance = 1e-8
  )
})
